#!/usr/bin/env node
import { main } from '../cli.mjs';

main(process.argv.slice(2)).catch((err) => {
  const msg = err && typeof err === 'object' && 'stack' in err ? err.stack : String(err);
  console.error(msg);
  process.exitCode = 1;
});

import { parseArgs } from 'node:util';
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import qrcodeTerminal from 'qrcode-terminal';

import { decodeQrFromPng } from './lib/qr.mjs';
import {
  normalizeCookiesPayload,
  cookiesToHeaderString,
  summarizeCookies,
} from './lib/cookies.mjs';

function usage() {
  return `xhs-skill

Usage:
  xhs-skill qr show --in <pngPath>
  xhs-skill qr show-text --text <string>

  xhs-skill cookies normalize --in <jsonPath> --out <outPath>
  xhs-skill cookies to-header --in <cookiesJsonPath>
  xhs-skill cookies status --in <cookiesJsonPath>

Notes:
  - QR decode currently supports PNG input (agent-browser-stealth should save screenshots as PNG).
  - cookies JSON can be either an array of cookies or an object containing {cookies:[...]}.
`;
}

function die(msg, code = 2) {
  const e = new Error(msg);
  e.exitCode = code;
  throw e;
}

async function ensureDirForFile(p) {
  await mkdir(dirname(p), { recursive: true });
}

async function cmdQrShow(argv) {
  const { values } = parseArgs({
    args: argv,
    options: {
      in: { type: 'string' },
      json: { type: 'boolean', default: false },
      ascii: { type: 'boolean', default: true },
    },
    allowPositionals: true,
  });

  const inPath = values.in ? resolve(values.in) : null;
  if (!inPath) die('Missing --in <pngPath>');

  const { text } = await decodeQrFromPng(inPath);
  if (values.json) {
    console.log(JSON.stringify({ qr_text: text, source_png: inPath }, null, 2));
    return;
  }

  console.log(text);
  if (values.ascii) {
    qrcodeTerminal.generate(text, { small: true });
  }
}

async function cmdQrShowText(argv) {
  const { values } = parseArgs({
    args: argv,
    options: {
      text: { type: 'string' },
      json: { type: 'boolean', default: false },
      ascii: { type: 'boolean', default: true },
    },
    allowPositionals: true,
  });

  const text = values.text;
  if (!text) die('Missing --text <string>');

  if (values.json) {
    console.log(JSON.stringify({ qr_text: text }, null, 2));
    return;
  }

  console.log(text);
  if (values.ascii) {
    qrcodeTerminal.generate(text, { small: true });
  }
}

async function cmdCookiesNormalize(argv) {
  const { values } = parseArgs({
    args: argv,
    options: {
      in: { type: 'string' },
      out: { type: 'string' },
    },
    allowPositionals: true,
  });

  const inPath = values.in ? resolve(values.in) : null;
  const outPath = values.out ? resolve(values.out) : null;
  if (!inPath) die('Missing --in <jsonPath>');
  if (!outPath) die('Missing --out <outPath>');

  const raw = await readFile(inPath, 'utf8');
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch {
    die(`Invalid JSON: ${inPath}`);
  }

  const normalized = normalizeCookiesPayload(parsed);
  await ensureDirForFile(outPath);
  await writeFile(outPath, JSON.stringify(normalized, null, 2) + '\n', 'utf8');
  console.log(`Wrote ${normalized.cookies.length} cookies to ${outPath}`);
}

async function cmdCookiesToHeader(argv) {
  const { values } = parseArgs({
    args: argv,
    options: {
      in: { type: 'string' },
      json: { type: 'boolean', default: false },
    },
    allowPositionals: true,
  });

  const inPath = values.in ? resolve(values.in) : null;
  if (!inPath) die('Missing --in <cookiesJsonPath>');

  const raw = await readFile(inPath, 'utf8');
  const parsed = JSON.parse(raw);
  const normalized = normalizeCookiesPayload(parsed);
  const header = cookiesToHeaderString(normalized.cookies);

  if (values.json) {
    console.log(JSON.stringify({ header, cookie_count: normalized.cookies.length }, null, 2));
    return;
  }
  console.log('Cookie: ' + header);
}

async function cmdCookiesStatus(argv) {
  const { values } = parseArgs({
    args: argv,
    options: {
      in: { type: 'string' },
      json: { type: 'boolean', default: false },
    },
    allowPositionals: true,
  });

  const inPath = values.in ? resolve(values.in) : null;
  if (!inPath) die('Missing --in <cookiesJsonPath>');

  const raw = await readFile(inPath, 'utf8');
  const parsed = JSON.parse(raw);
  const normalized = normalizeCookiesPayload(parsed);
  const summary = summarizeCookies(normalized.cookies);

  if (values.json) {
    console.log(JSON.stringify({ ...summary, source: inPath }, null, 2));
    return;
  }

  console.log(`cookies: ${summary.count}`);
  console.log(`domains: ${summary.domains.join(', ') || '(none)'}`);
  console.log(`sessionCookies: ${summary.sessionCount}`);
  console.log(`persistentCookies: ${summary.persistentCount}`);
  if (summary.earliestExpiry) console.log(`earliestExpiry: ${summary.earliestExpiry}`);
  if (summary.latestExpiry) console.log(`latestExpiry: ${summary.latestExpiry}`);
}

export async function main(argv) {
  const [cmd, sub, ...rest] = argv;

  if (!cmd || cmd === '-h' || cmd === '--help' || cmd === 'help') {
    console.log(usage());
    return;
  }

  try {
    if (cmd === 'qr' && sub === 'show') return await cmdQrShow(rest);
    if (cmd === 'qr' && sub === 'show-text') return await cmdQrShowText(rest);

    if (cmd === 'cookies' && sub === 'normalize') return await cmdCookiesNormalize(rest);
    if (cmd === 'cookies' && sub === 'to-header') return await cmdCookiesToHeader(rest);
    if (cmd === 'cookies' && sub === 'status') return await cmdCookiesStatus(rest);

    die(`Unknown command: ${cmd} ${sub || ''}`.trim());
  } catch (e) {
    if (e && typeof e === 'object' && 'exitCode' in e) {
      console.error(e.message);
      process.exitCode = e.exitCode;
      return;
    }
    throw e;
  }
}

function asString(v) {
  if (v === null || v === undefined) return '';
  return String(v);
}

function pick(obj, keys) {
  for (const k of keys) {
    if (obj && Object.prototype.hasOwnProperty.call(obj, k) && obj[k] !== undefined) return obj[k];
  }
  return undefined;
}

function normalizeSameSite(v) {
  const s = asString(v).toLowerCase();
  if (!s) return undefined;
  if (s === 'lax') return 'Lax';
  if (s === 'strict') return 'Strict';
  if (s === 'none') return 'None';
  return undefined;
}

function normalizeExpires(v) {
  if (v === null || v === undefined || v === '') return undefined;

  // Common formats:
  // - Playwright uses seconds since epoch (number)
  // - Chrome exports can use milliseconds or ISO strings
  if (typeof v === 'number') {
    if (v <= 0) return undefined;
    // Heuristic: treat > 10^12 as ms
    const ms = v > 1e12 ? v : v * 1000;
    return new Date(ms).toISOString();
  }

  const s = asString(v).trim();
  if (!s) return undefined;

  const n = Number(s);
  if (!Number.isNaN(n)) {
    const ms = n > 1e12 ? n : n * 1000;
    return new Date(ms).toISOString();
  }

  const d = new Date(s);
  if (!Number.isNaN(d.getTime())) return d.toISOString();
  return undefined;
}

export function normalizeCookieObject(c) {
  if (!c || typeof c !== 'object') return null;

  const name = asString(pick(c, ['name', 'Name'])).trim();
  const value = asString(pick(c, ['value', 'Value'])).trim();
  if (!name) return null;

  const domain = asString(pick(c, ['domain', 'Domain'])).trim() || '.xiaohongshu.com';
  const path = asString(pick(c, ['path', 'Path'])).trim() || '/';

  const httpOnly = Boolean(pick(c, ['httpOnly', 'http_only', 'HttpOnly']));
  const secure = Boolean(pick(c, ['secure', 'Secure']));

  const sameSite = normalizeSameSite(pick(c, ['sameSite', 'same_site', 'SameSite']));
  const expires = normalizeExpires(pick(c, ['expires', 'expirationDate', 'expiry', 'Expires', 'Expiration']));

  return {
    name,
    value,
    domain,
    path,
    httpOnly,
    secure,
    sameSite,
    expires,
  };
}

export function normalizeCookiesPayload(input) {
  let cookiesRaw = input;
  if (input && typeof input === 'object' && !Array.isArray(input)) {
    // Supported shapes:
    // - [...]
    // - { cookies: [...] }
    // - { data: { cookies: [...] } } (agent-browser-stealth --json)
    // - { success: true, data: { cookies: [...] }, error: null } (agent-browser-stealth --json)
    if (Array.isArray(input.cookies)) {
      cookiesRaw = input.cookies;
    } else if (input.data && typeof input.data === 'object' && Array.isArray(input.data.cookies)) {
      cookiesRaw = input.data.cookies;
    }
  }

  if (!Array.isArray(cookiesRaw)) {
    throw new Error('Unsupported cookies JSON: expected array or {cookies:[...]}');
  }

  const cookies = [];
  for (const c of cookiesRaw) {
    const n = normalizeCookieObject(c);
    if (n) cookies.push(n);
  }

  if (cookies.length === 0) {
    throw new Error('No cookies parsed after normalization');
  }

  return {
    generated_at: new Date().toISOString(),
    format: 'cookie_list_v1',
    cookies,
  };
}

export function cookiesToHeaderString(cookies) {
  const parts = [];
  for (const c of cookies) {
    if (!c || typeof c !== 'object') continue;
    const name = asString(c.name).trim();
    const value = asString(c.value);
    if (!name) continue;
    parts.push(`${name}=${value}`);
  }
  return parts.join('; ');
}

export function summarizeCookies(cookies) {
  const domains = new Set();
  let sessionCount = 0;
  let persistentCount = 0;
  let earliest = null;
  let latest = null;

  for (const c of cookies) {
    if (!c || typeof c !== 'object') continue;
    if (c.domain) domains.add(String(c.domain));

    if (c.expires) {
      persistentCount += 1;
      const t = new Date(c.expires).getTime();
      if (!Number.isNaN(t)) {
        if (earliest === null || t < earliest) earliest = t;
        if (latest === null || t > latest) latest = t;
      }
    } else {
      sessionCount += 1;
    }
  }

  return {
    count: cookies.length,
    domains: Array.from(domains).sort(),
    sessionCount,
    persistentCount,
    earliestExpiry: earliest ? new Date(earliest).toISOString() : null,
    latestExpiry: latest ? new Date(latest).toISOString() : null,
  };
}

import { readFile } from 'node:fs/promises';

function u32be(buf, off) {
  return (buf[off] << 24) | (buf[off + 1] << 16) | (buf[off + 2] << 8) | buf[off + 3];
}

function u16be(buf, off) {
  return (buf[off] << 8) | buf[off + 1];
}

function isPng(buf) {
  return (
    buf.length >= 24 &&
    buf[0] === 0x89 &&
    buf[1] === 0x50 &&
    buf[2] === 0x4e &&
    buf[3] === 0x47 &&
    buf[4] === 0x0d &&
    buf[5] === 0x0a &&
    buf[6] === 0x1a &&
    buf[7] === 0x0a
  );
}

function parsePngSize(buf) {
  // PNG signature(8) + IHDR length(4) + type(4) => width starts at offset 16
  const width = u32be(buf, 16);
  const height = u32be(buf, 20);
  if (!Number.isFinite(width) || !Number.isFinite(height) || width <= 0 || height <= 0) {
    throw new Error('Invalid PNG IHDR size');
  }
  return { width, height, format: 'png' };
}

function isJpeg(buf) {
  return buf.length >= 4 && buf[0] === 0xff && buf[1] === 0xd8;
}

function parseJpegSize(buf) {
  // Walk markers until SOF0/SOF2.
  let i = 2; // after SOI
  while (i + 4 < buf.length) {
    if (buf[i] !== 0xff) {
      i += 1;
      continue;
    }
    // skip fill bytes 0xFF
    while (i < buf.length && buf[i] === 0xff) i += 1;
    if (i >= buf.length) break;
    const marker = buf[i];
    i += 1;

    // markers without length
    if (marker === 0xd9 || marker === 0xda) break; // EOI / SOS
    if (i + 2 > buf.length) break;
    const segLen = u16be(buf, i);
    if (segLen < 2) break;
    const segStart = i + 2;

    // SOF0(0xC0) / SOF2(0xC2) baseline/progressive
    if (marker === 0xc0 || marker === 0xc2) {
      if (segStart + 5 >= buf.length) break;
      const height = u16be(buf, segStart + 1);
      const width = u16be(buf, segStart + 3);
      if (width <= 0 || height <= 0) throw new Error('Invalid JPEG SOF size');
      return { width, height, format: 'jpeg' };
    }

    i = i + segLen;
  }
  throw new Error('Unsupported JPEG (no SOF marker found)');
}

export async function getImageSize(path) {
  const buf = await readFile(path);
  if (isPng(buf)) return parsePngSize(buf);
  if (isJpeg(buf)) return parseJpegSize(buf);
  throw new Error('Unsupported image format (only PNG/JPEG)');
}

import { readFile } from 'node:fs/promises';
import jsQR from 'jsqr';
import { PNG } from 'pngjs';

export async function decodeQrFromPng(pngPath) {
  const buf = await readFile(pngPath);
  let png;
  try {
    png = PNG.sync.read(buf);
  } catch (e) {
    throw new Error(`Failed to read PNG: ${pngPath}`);
  }

  const code = jsQR(new Uint8ClampedArray(png.data), png.width, png.height);
  if (!code || !code.data) {
    throw new Error(`No QR code detected in PNG: ${pngPath}`);
  }

  return {
    text: code.data,
    width: png.width,
    height: png.height,
  };
}

{
  "name": "xhs-skill",
  "version": "1.0.1",
  "private": true,
  "type": "module",
  "description": "Local CLI helpers for xhs-skill (QR decode + cookies utils)",
  "bin": {
    "xhs-skill": "./bin/xhs-skill.mjs"
  },
  "engines": {
    "node": ">=18"
  },
  "dependencies": {
    "jsqr": "^1.4.0",
    "pngjs": "^7.0.0",
    "qrcode-terminal": "^0.12.0"
  }
}

#!/usr/bin/env node
import { parseArgs } from 'node:util';
import { readFile, stat } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const DEFAULT_POLICY_PATH = path.resolve(__dirname, '../config/review_policy.json');
const DEFAULT_TAXONOMY_PATH = path.resolve(__dirname, '../config/review_taxonomy.json');

const DEFAULT_POLICY = {
  text: {
    min_body_len: 80,
    blocked_link_tlds: ['com', 'cn', 'net', 'org', 'io', 'me', 'co', 'app', 'dev'],
    hard_block_phrases: [
      '100%不被识别',
      '100% undetectable',
      '稳赚不赔',
      '保本保收益',
      '包治百病',
      '私信领取',
      '加微信',
      'vx:',
      'vx：',
    ],
    high_risk_patterns: [
      '(治愈|根治|包治|药到病除)',
      '(保证收益|稳赚|翻倍|保本)',
      '(兼职|刷单|返利|薅羊毛教程)',
      '(加微|加v|私聊我|私信我领取)',
    ],
    medium_risk_keywords: [
      '最强',
      '必买',
      '立刻下单',
      '免费领',
      '内幕',
      '黑科技',
      '秒过',
      '保姆级',
    ],
  },
  source: {
    min_evidence_snippet_len: 16,
    min_key_facts_count: 2,
  },
  ai: {
    provider: 'auto',
    base_url: 'https://api.openai.com/v1',
    model: 'gpt-4o-mini',
    temperature: 0,
    timeout_ms: 30000,
    max_images: 3,
    max_inline_image_bytes: 1200000,
    send_images: true,
  },
  decision: {
    pass_max_risk_score: 28,
    block_min_risk_score: 70,
    block_on_review: true,
    block_on_ai_error: true,
    max_hits: 12,
    review_queue: {
      enabled: true,
      name: 'xhs_manual_review',
      owner: 'content_safety',
      default_priority: 'P2',
      block_priority: 'P1',
      review_priority: 'P2',
      sla_minutes: 60,
    },
    severity_score: {
      low: 8,
      medium: 20,
      high: 45,
    },
  },
};

function usage() {
  return `review_publish_payload

Usage:
  node ./scripts/review_publish_payload.mjs --in <payloadJsonPath> [--mode hot] [--json]
  node ./scripts/review_publish_payload.mjs --in <payloadJsonPath> [--policy ./skills/xhs-skill/config/review_policy.json]
  node ./scripts/review_publish_payload.mjs --in <payloadJsonPath> [--taxonomy ./skills/xhs-skill/config/review_taxonomy.json]
  node ./scripts/review_publish_payload.mjs --in <payloadJsonPath> [--ai-provider auto|openai|none] [--require-ai on|off]
`;
}

function str(v) {
  return String(v || '').trim();
}

function pickArray(v) {
  return Array.isArray(v) ? v : [];
}

function toPositiveInt(value, fallback) {
  const n = Number(value);
  if (!Number.isFinite(n) || n <= 0) return fallback;
  return Math.floor(n);
}

function toFiniteNumber(value, fallback) {
  const n = Number(value);
  if (!Number.isFinite(n)) return fallback;
  return n;
}

function parseToggle(value, fallback = true) {
  const s = String(value ?? '').trim().toLowerCase();
  if (!s) return fallback;
  if (['1', 'true', 'on', 'yes', 'y'].includes(s)) return true;
  if (['0', 'false', 'off', 'no', 'n'].includes(s)) return false;
  return fallback;
}

function uniqueList(items) {
  const out = [];
  const seen = new Set();
  for (const it of items) {
    const v = str(it);
    if (!v) continue;
    const key = v.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(v);
  }
  return out;
}

function normalizeTag(tag) {
  const v = str(tag);
  if (!v) return '';
  return v.startsWith('#') ? v : `#${v}`;
}

function isPlainObject(v) {
  return !!v && typeof v === 'object' && !Array.isArray(v);
}

function deepMerge(base, override) {
  if (Array.isArray(base)) {
    return Array.isArray(override) ? override : [...base];
  }
  if (isPlainObject(base)) {
    const out = { ...base };
    if (isPlainObject(override)) {
      for (const key of Object.keys(override)) {
        if (Object.prototype.hasOwnProperty.call(base, key)) {
          out[key] = deepMerge(base[key], override[key]);
        } else {
          out[key] = override[key];
        }
      }
    }
    return out;
  }
  return override === undefined ? base : override;
}

async function loadPolicy(filePath) {
  const policyPath = str(filePath);
  if (!policyPath) {
    throw new Error('Missing review policy path');
  }
  try {
    const raw = await readFile(policyPath, 'utf8');
    const parsed = JSON.parse(raw);
    if (!isPlainObject(parsed)) {
      throw new Error(`Review policy must be a JSON object: ${policyPath}`);
    }
    return { exists: true, path: policyPath, overrides: parsed };
  } catch (e) {
    throw new Error(`Failed to load review policy "${policyPath}": ${e?.message || String(e)}`);
  }
}

function parseFirstJsonObject(text) {
  const s = str(text);
  if (!s) return null;
  const i = s.indexOf('{');
  const j = s.lastIndexOf('}');
  if (i < 0 || j <= i) return null;
  try {
    return JSON.parse(s.slice(i, j + 1));
  } catch {
    return null;
  }
}

function containsLinkLike(text, blockedTlds) {
  const s = String(text || '').trim();
  if (!s) return false;
  if (/https?:\/\//i.test(s)) return true;
  if (/www\./i.test(s)) return true;
  const tlds = uniqueList(pickArray(blockedTlds).map((x) => str(x).toLowerCase()).filter(Boolean));
  if (!tlds.length) return false;
  const tldPattern = tlds.map((x) => x.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|');
  if (!tldPattern) return false;
  const domainLike = new RegExp(`\\b[a-z0-9-]+\\.(${tldPattern})\\b`, 'i');
  return domainLike.test(s);
}

function compileRegexList(patterns) {
  const out = [];
  for (const raw of pickArray(patterns)) {
    const source = str(raw);
    if (!source) continue;
    try {
      out.push(new RegExp(source, 'i'));
    } catch {
      // ignore invalid regex from custom policy
    }
  }
  return out;
}

function normalizeRiskPath(pathLike) {
  if (Array.isArray(pathLike)) {
    return pathLike.map((x) => str(x).toLowerCase()).filter(Boolean).slice(0, 8);
  }
  const s = str(pathLike);
  if (!s) return [];
  return s
    .split(/[>|/]/)
    .map((x) => str(x).toLowerCase())
    .filter(Boolean)
    .slice(0, 8);
}

function riskPathText(pathArr) {
  const parts = normalizeRiskPath(pathArr);
  return parts.join(' > ');
}

async function loadTaxonomy(filePath) {
  const taxonomyPath = str(filePath);
  if (!taxonomyPath) {
    throw new Error('Missing review taxonomy path');
  }
  try {
    const raw = await readFile(taxonomyPath, 'utf8');
    const parsed = JSON.parse(raw);
    if (!isPlainObject(parsed)) {
      throw new Error(`Review taxonomy must be a JSON object: ${taxonomyPath}`);
    }
    return { exists: true, path: taxonomyPath, value: parsed };
  } catch (e) {
    throw new Error(`Failed to load review taxonomy "${taxonomyPath}": ${e?.message || String(e)}`);
  }
}

function buildTaxonomyIndex(rawTaxonomy) {
  const ruleIdToPath = new Map();
  const categoryToPath = new Map();
  const keywordMatchers = [];
  const declaredPaths = [];

  for (const item of pickArray(rawTaxonomy?.paths)) {
    const id = str(item?.id);
    const pathArr = normalizeRiskPath(item?.path || id);
    if (!pathArr.length) continue;
    declaredPaths.push({ id: id || riskPathText(pathArr), path: pathArr, label: str(item?.label) || null });

    for (const rid of pickArray(item?.rule_hit_ids)) {
      const key = str(rid).toLowerCase();
      if (!key) continue;
      ruleIdToPath.set(key, pathArr);
    }
    for (const cat of pickArray(item?.categories)) {
      const key = str(cat).toLowerCase();
      if (!key) continue;
      categoryToPath.set(key, pathArr);
    }
    for (const kw of pickArray(item?.keywords)) {
      const key = str(kw).toLowerCase();
      if (!key) continue;
      keywordMatchers.push({ keyword: key, path: pathArr });
    }
  }

  return {
    declared_paths: declaredPaths,
    rule_id_to_path: ruleIdToPath,
    category_to_path: categoryToPath,
    keyword_matchers: keywordMatchers.sort((a, b) => b.keyword.length - a.keyword.length),
  };
}

function fallbackRiskPathByHitId(hitId) {
  const id = str(hitId).toLowerCase();
  if (!id) return [];
  if (id === 'link_or_source_url_violation') return ['content', 'diversion', 'link'];
  if (id === 'hard_block_phrases' || id === 'high_risk_pattern') return ['content', 'marketing', 'false_promise'];
  if (id === 'medium_risk_keywords') return ['content', 'marketing', 'suspicious_phrase'];
  if (id === 'source_traceability_weak') return ['content', 'authenticity', 'traceability'];
  if (id === 'body_too_short') return ['content', 'quality', 'low_information'];
  return [];
}

function inferRiskPathFromText(text, taxonomyIndex) {
  const s = str(text).toLowerCase();
  if (!s) return [];
  for (const m of taxonomyIndex.keyword_matchers) {
    if (s.includes(m.keyword)) return m.path;
  }
  return [];
}

function inferRiskPathFromCategory(category, taxonomyIndex) {
  const key = str(category).toLowerCase();
  if (!key) return [];
  if (taxonomyIndex.category_to_path.has(key)) {
    return taxonomyIndex.category_to_path.get(key);
  }
  return inferRiskPathFromText(key, taxonomyIndex);
}

function inferRiskPathForRuleHit(hitId, hitText, taxonomyIndex) {
  const hitKey = str(hitId).toLowerCase();
  if (hitKey && taxonomyIndex.rule_id_to_path.has(hitKey)) {
    return taxonomyIndex.rule_id_to_path.get(hitKey);
  }
  const byText = inferRiskPathFromText(hitText, taxonomyIndex);
  if (byText.length) return byText;
  return fallbackRiskPathByHitId(hitId);
}

function evidenceQuote(v) {
  const s = str(v);
  return s ? s.slice(0, 240) : '';
}

function collectPayload(payload) {
  const topic = str(payload?.topic);
  const sourceName = str(payload?.source?.name);
  const sourceUrl = str(payload?.source?.url);
  const sourceDate = str(payload?.source?.date);
  const sourceEvidenceSnippet = str(payload?.source?.evidence_snippet);
  const sourceKeyFacts = uniqueList(pickArray(payload?.source?.key_facts).map((x) => str(x)).filter(Boolean));

  const title = str(payload?.post?.title);
  const body = str(payload?.post?.body);
  const tags = uniqueList(pickArray(payload?.post?.tags).map((x) => normalizeTag(x)).filter(Boolean));
  const realTopics = uniqueList(pickArray(payload?.post?.real_topics).map((x) => normalizeTag(x)).filter(Boolean));
  const media = pickArray(payload?.post?.media).map((x) => str(x)).filter(Boolean);

  const textBundle = [
    `topic: ${topic}`,
    `title: ${title}`,
    `body: ${body}`,
    `tags: ${tags.join(' ')}`,
    `real_topics: ${realTopics.join(' ')}`,
    `source_name: ${sourceName}`,
    `source_url: ${sourceUrl}`,
    `source_date: ${sourceDate}`,
    `source_evidence_snippet: ${sourceEvidenceSnippet}`,
    `source_key_facts: ${sourceKeyFacts.join(' | ')}`,
  ].join('\n');

  return {
    topic,
    sourceName,
    sourceUrl,
    sourceDate,
    sourceEvidenceSnippet,
    sourceKeyFacts,
    title,
    body,
    tags,
    realTopics,
    media,
    textBundle,
  };
}

function scoreHits(hits, severityScore) {
  let score = 0;
  for (const hit of hits) {
    const sev = str(hit?.severity || 'low').toLowerCase();
    score += toPositiveInt(severityScore?.[sev], 8);
  }
  return Math.min(100, score);
}

function buildRuleLayer(collected, policy, mode, taxonomyIndex) {
  const hits = [];
  const addHit = ({ id, severity, message, evidence = null, hard_block = false, risk_path = [] }) => {
    const riskPath = normalizeRiskPath(risk_path).length
      ? normalizeRiskPath(risk_path)
      : inferRiskPathForRuleHit(id, `${message}\n${JSON.stringify(evidence || '')}`, taxonomyIndex);

    let evidenceItems = [];
    if (typeof evidence === 'string') {
      evidenceItems = [{ quote: evidenceQuote(evidence), severity: str(severity).toLowerCase(), risk_path: riskPath }];
    } else if (Array.isArray(evidence)) {
      evidenceItems = evidence
        .map((x) => ({ quote: evidenceQuote(x), severity: str(severity).toLowerCase(), risk_path: riskPath }))
        .filter((x) => x.quote);
    } else if (evidence && typeof evidence === 'object') {
      const snippet = JSON.stringify(evidence);
      evidenceItems = [{ quote: evidenceQuote(snippet), severity: str(severity).toLowerCase(), risk_path: riskPath }];
    }

    hits.push({
      id,
      severity,
      message,
      evidence,
      evidence_items: evidenceItems.slice(0, 4),
      hard_block: !!hard_block,
      risk_path: riskPath,
      risk_path_text: riskPathText(riskPath),
    });
  };

  const bodyLen = [...collected.body].length;
  const minBodyLen = toPositiveInt(policy?.text?.min_body_len, 80);
  if (bodyLen < minBodyLen) {
    addHit({
      id: 'body_too_short',
      severity: 'medium',
      message: `正文长度不足: ${bodyLen} < ${minBodyLen}`,
      evidence: collected.body.slice(0, 120),
    });
  }

  const blockedTlds = pickArray(policy?.text?.blocked_link_tlds);
  const links = {
    title: containsLinkLike(collected.title, blockedTlds),
    body: containsLinkLike(collected.body, blockedTlds),
    tags: collected.tags.some((x) => containsLinkLike(x, blockedTlds)),
    real_topics: collected.realTopics.some((x) => containsLinkLike(x, blockedTlds)),
    source_url_is_http: /^https?:\/\//i.test(collected.sourceUrl),
  };
  if (links.title || links.body || links.tags || links.real_topics || !links.source_url_is_http) {
    addHit({
      id: 'link_or_source_url_violation',
      severity: 'high',
      message: '检测到链接导流风险或来源 URL 非 http/https',
      evidence: links,
      hard_block: true,
    });
  }

  const lowerText = `${collected.title}\n${collected.body}\n${collected.tags.join(' ')}\n${collected.realTopics.join(' ')}`.toLowerCase();
  const hardPhrases = pickArray(policy?.text?.hard_block_phrases).map((x) => str(x).toLowerCase()).filter(Boolean);
  const hardPhraseHits = hardPhrases.filter((p) => lowerText.includes(p));
  if (hardPhraseHits.length) {
    addHit({
      id: 'hard_block_phrases',
      severity: 'high',
      message: '命中硬拦截短语',
      evidence: hardPhraseHits,
      hard_block: true,
    });
  }

  const highPatterns = compileRegexList(policy?.text?.high_risk_patterns);
  const highPatternHits = [];
  for (const re of highPatterns) {
    const m = `${collected.title}\n${collected.body}`.match(re);
    if (m && m[0]) highPatternHits.push(m[0]);
  }
  if (highPatternHits.length) {
    addHit({
      id: 'high_risk_pattern',
      severity: 'high',
      message: '命中高风险表达模式',
      evidence: uniqueList(highPatternHits),
      hard_block: false,
    });
  }

  const mediumKeywords = pickArray(policy?.text?.medium_risk_keywords).map((x) => str(x).toLowerCase()).filter(Boolean);
  const mediumHits = mediumKeywords.filter((k) => lowerText.includes(k));
  if (mediumHits.length) {
    addHit({
      id: 'medium_risk_keywords',
      severity: 'medium',
      message: '命中可疑营销表达',
      evidence: mediumHits,
      hard_block: false,
    });
  }

  const minEvidenceSnippetLen = toPositiveInt(policy?.source?.min_evidence_snippet_len, 16);
  const minKeyFactsCount = toPositiveInt(policy?.source?.min_key_facts_count, 2);
  if (collected.sourceEvidenceSnippet.length < minEvidenceSnippetLen || collected.sourceKeyFacts.length < minKeyFactsCount) {
    addHit({
      id: 'source_traceability_weak',
      severity: mode === 'hot' ? 'high' : 'medium',
      message: '来源可追溯字段不足（evidence_snippet/key_facts）',
      evidence: {
        evidence_snippet_len: collected.sourceEvidenceSnippet.length,
        min_evidence_snippet_len: minEvidenceSnippetLen,
        key_facts_count: collected.sourceKeyFacts.length,
        min_key_facts_count: minKeyFactsCount,
      },
    });
  }

  const severityScore = policy?.decision?.severity_score || {};
  const rawRiskScore = scoreHits(hits, severityScore);
  const passMax = toFiniteNumber(policy?.decision?.pass_max_risk_score, 28);
  const blockMin = toFiniteNumber(policy?.decision?.block_min_risk_score, 70);
  const hardBlocked = hits.some((x) => !!x.hard_block);

  let decision = 'pass';
  if (hardBlocked || rawRiskScore >= blockMin) {
    decision = 'block';
  } else if (rawRiskScore > passMax) {
    decision = 'review';
  }

  const maxHits = toPositiveInt(policy?.decision?.max_hits, 12);
  const hitPaths = uniqueList(hits.map((x) => riskPathText(x.risk_path)).filter(Boolean));
  return {
    ok: decision === 'pass',
    decision,
    risk_score: rawRiskScore,
    hard_blocked: hardBlocked,
    thresholds: {
      pass_max_risk_score: passMax,
      block_min_risk_score: blockMin,
    },
    links,
    risk_paths: hitPaths,
    hits: hits.slice(0, maxHits),
  };
}

function mimeByPath(filePath) {
  const s = String(filePath || '').toLowerCase();
  if (s.endsWith('.png')) return 'image/png';
  if (s.endsWith('.jpg') || s.endsWith('.jpeg')) return 'image/jpeg';
  if (s.endsWith('.webp')) return 'image/webp';
  return null;
}

async function loadAiImages(media, policy) {
  const maxImages = toPositiveInt(policy?.ai?.max_images, 3);
  const maxInlineBytes = toPositiveInt(policy?.ai?.max_inline_image_bytes, 1200000);
  const imagePaths = media.filter((x) => !!mimeByPath(x)).slice(0, maxImages);
  const out = [];

  for (const p of imagePaths) {
    const absPath = path.resolve(p);
    const mime = mimeByPath(absPath);
    if (!mime) continue;

    try {
      const st = await stat(absPath);
      const sizeBytes = Number(st.size) || 0;
      if (sizeBytes <= 0) {
        out.push({ path: absPath, ok: false, reason: 'empty_file' });
        continue;
      }
      if (sizeBytes > maxInlineBytes) {
        out.push({ path: absPath, ok: false, reason: 'too_large', size_bytes: sizeBytes, max_inline_bytes: maxInlineBytes });
        continue;
      }
      const buff = await readFile(absPath);
      const dataUrl = `data:${mime};base64,${buff.toString('base64')}`;
      out.push({ path: absPath, ok: true, size_bytes: sizeBytes, mime, data_url: dataUrl });
    } catch (e) {
      out.push({ path: absPath, ok: false, reason: e?.message || String(e) });
    }
  }

  return out;
}

function sanitizeAiJson(json, taxonomyIndex) {
  const decisionRaw = str(json?.decision).toLowerCase();
  const decision = ['pass', 'review', 'block'].includes(decisionRaw) ? decisionRaw : 'review';
  const riskScore = Math.max(0, Math.min(100, toFiniteNumber(json?.risk_score, 60)));
  const reasons = pickArray(json?.reasons).map((x) => str(x)).filter(Boolean).slice(0, 12);
  const evidence = pickArray(json?.evidence)
    .map((x) => ({
      quote: str(x?.quote),
      category: str(x?.category),
      severity: str(x?.severity).toLowerCase() || 'medium',
      risk_path: normalizeRiskPath(x?.risk_path || x?.path),
    }))
    .filter((x) => x.quote)
    .map((x) => {
      const inferredPath =
        x.risk_path.length
          ? x.risk_path
          : inferRiskPathFromCategory(x.category, taxonomyIndex).length
            ? inferRiskPathFromCategory(x.category, taxonomyIndex)
            : inferRiskPathFromText(x.quote, taxonomyIndex);
      return {
        ...x,
        risk_path: inferredPath,
        risk_path_text: riskPathText(inferredPath),
      };
    })
    .slice(0, 12);

  const riskPaths = uniqueList(evidence.map((x) => x.risk_path_text).filter(Boolean));

  return {
    decision,
    risk_score: riskScore,
    reasons,
    evidence,
    risk_paths: riskPaths,
    need_human: !!json?.need_human,
  };
}

async function callOpenAiReview({ collected, policy, mode, ruleLayer, taxonomyIndex, requestedProvider, requireAi }) {
  const providerRaw = str(requestedProvider || policy?.ai?.provider || 'auto').toLowerCase();
  const openAiKey = str(process.env.OPENAI_API_KEY);

  let provider = providerRaw;
  if (provider === 'auto') {
    provider = openAiKey ? 'openai' : 'none';
  }

  if (provider === 'none') {
    return {
      enabled: false,
      used: false,
      ok: !requireAi,
      provider: 'none',
      reason: requireAi ? 'ai_required_but_disabled' : 'ai_disabled',
    };
  }

  if (provider !== 'openai') {
    return {
      enabled: true,
      used: false,
      ok: false,
      provider,
      reason: `unsupported_ai_provider:${provider}`,
    };
  }

  if (!openAiKey) {
    return {
      enabled: true,
      used: false,
      ok: false,
      provider: 'openai',
      reason: 'OPENAI_API_KEY missing',
    };
  }

  const baseUrl = str(process.env.OPENAI_BASE_URL || policy?.ai?.base_url || 'https://api.openai.com/v1').replace(/\/$/, '');
  const model = str(process.env.OPENAI_MODEL || policy?.ai?.model || 'gpt-4o-mini');
  const temperature = toFiniteNumber(policy?.ai?.temperature, 0);
  const timeoutMs = toPositiveInt(policy?.ai?.timeout_ms, 30000);
  const sendImages = parseToggle(policy?.ai?.send_images, true);

  const images = sendImages ? await loadAiImages(collected.media, policy) : [];
  const usableImages = images.filter((x) => x.ok && x.data_url);

  const systemPrompt = [
    '你是小红书发布前风控审核器。',
    '目标：识别违规/高风险内容并给出可解释证据。',
    '输出必须是 JSON 对象，不要输出 markdown，不要输出多余文本。',
    '字段要求：',
    '- decision: pass | review | block',
    '- risk_score: 0-100 数字',
    '- reasons: 字符串数组（简短）',
    '- evidence: 数组，每项含 quote/category/severity/risk_path(数组，层级路径)',
    '- need_human: 布尔值',
  ].join('\n');

  const userText = [
    `mode: ${mode}`,
    'payload:',
    collected.textBundle,
    'rule_layer_summary:',
    JSON.stringify(
      {
        decision: ruleLayer.decision,
        risk_score: ruleLayer.risk_score,
        hits: ruleLayer.hits,
      },
      null,
      2
    ),
    'risk_taxonomy_paths:',
    JSON.stringify(taxonomyIndex.declared_paths, null, 2),
    '请基于文本与图片（如果有）做多模态风险评估。',
  ].join('\n');

  const userContent = [{ type: 'text', text: userText }];
  for (const img of usableImages) {
    userContent.push({
      type: 'image_url',
      image_url: {
        url: img.data_url,
      },
    });
  }

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const resp = await fetch(`${baseUrl}/chat/completions`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${openAiKey}`,
      },
      body: JSON.stringify({
        model,
        temperature,
        response_format: { type: 'json_object' },
        messages: [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: userContent },
        ],
      }),
      signal: controller.signal,
    });

    const raw = await resp.text();
    if (!resp.ok) {
      return {
        enabled: true,
        used: true,
        ok: false,
        provider: 'openai',
        model,
        status: resp.status,
        reason: `openai_http_${resp.status}`,
        error: str(raw).slice(0, 300),
        images: images.map((x) => ({ path: x.path, ok: x.ok, reason: x.reason || null, size_bytes: x.size_bytes || null })),
      };
    }

    const parsed = JSON.parse(raw);
    const content = parsed?.choices?.[0]?.message?.content;
    let contentText = '';
    if (typeof content === 'string') {
      contentText = content;
    } else if (Array.isArray(content)) {
      contentText = content
        .map((item) => (item && typeof item === 'object' && typeof item.text === 'string' ? item.text : ''))
        .filter(Boolean)
        .join('\n');
    }

    const aiJson = parseFirstJsonObject(contentText);
    if (!aiJson) {
      return {
        enabled: true,
        used: true,
        ok: false,
        provider: 'openai',
        model,
        reason: 'invalid_ai_json',
        raw_preview: str(contentText).slice(0, 300),
        images: images.map((x) => ({ path: x.path, ok: x.ok, reason: x.reason || null, size_bytes: x.size_bytes || null })),
      };
    }

    const sanitized = sanitizeAiJson(aiJson, taxonomyIndex);
    return {
      enabled: true,
      used: true,
      ok: true,
      provider: 'openai',
      model,
      ...sanitized,
      images: images.map((x) => ({ path: x.path, ok: x.ok, reason: x.reason || null, size_bytes: x.size_bytes || null })),
    };
  } catch (e) {
    return {
      enabled: true,
      used: true,
      ok: false,
      provider: 'openai',
      model,
      reason: e?.name === 'AbortError' ? 'ai_timeout' : 'ai_request_failed',
      error: e?.message || String(e),
    };
  } finally {
    clearTimeout(timer);
  }
}

function mergeDecision(ruleLayer, aiLayer, policy, requireAi) {
  const passMax = toFiniteNumber(policy?.decision?.pass_max_risk_score, 28);
  const blockMin = toFiniteNumber(policy?.decision?.block_min_risk_score, 70);
  const blockOnReview = parseToggle(policy?.decision?.block_on_review, true);
  const blockOnAiError = parseToggle(policy?.decision?.block_on_ai_error, true);

  if (ruleLayer.decision === 'block') {
    return {
      decision: 'block',
      risk_score: ruleLayer.risk_score,
      reason: 'rule_layer_block',
    };
  }

  if (requireAi && (!aiLayer.used || !aiLayer.ok)) {
    return {
      decision: 'block',
      risk_score: Math.max(ruleLayer.risk_score, 80),
      reason: 'ai_required_but_unavailable',
    };
  }

  if (aiLayer.used && !aiLayer.ok) {
    if (blockOnAiError) {
      return {
        decision: 'block',
        risk_score: Math.max(ruleLayer.risk_score, 75),
        reason: 'ai_layer_error',
      };
    }
    return {
      decision: ruleLayer.decision,
      risk_score: ruleLayer.risk_score,
      reason: 'ai_layer_error_but_ignored',
    };
  }

  if (aiLayer.used && aiLayer.ok) {
    const combinedRisk = Math.round(Math.max(ruleLayer.risk_score, toFiniteNumber(aiLayer.risk_score, 0)));

    if (aiLayer.decision === 'block' || combinedRisk >= blockMin) {
      return {
        decision: 'block',
        risk_score: combinedRisk,
        reason: 'ai_or_combined_block',
      };
    }

    if (aiLayer.decision === 'review' || ruleLayer.decision === 'review' || combinedRisk > passMax) {
      return {
        decision: blockOnReview ? 'block' : 'review',
        risk_score: combinedRisk,
        reason: blockOnReview ? 'review_treated_as_block' : 'needs_review',
      };
    }

    return {
      decision: 'pass',
      risk_score: combinedRisk,
      reason: 'rule_and_ai_pass',
    };
  }

  return {
    decision: ruleLayer.decision,
    risk_score: ruleLayer.risk_score,
    reason: 'rule_layer_only',
  };
}

function severityRank(severity) {
  const s = str(severity).toLowerCase();
  if (s === 'high') return 3;
  if (s === 'medium') return 2;
  return 1;
}

function collectAllRiskPaths(ruleLayer, aiLayer) {
  const out = [];
  const add = (pathArr) => {
    const p = normalizeRiskPath(pathArr);
    if (!p.length) return;
    const key = riskPathText(p);
    if (!key) return;
    if (out.some((x) => riskPathText(x) === key)) return;
    out.push(p);
  };

  for (const h of pickArray(ruleLayer?.hits)) add(h?.risk_path);
  for (const e of pickArray(aiLayer?.evidence)) add(e?.risk_path);
  return out;
}

function pickPrimaryRiskPath(ruleLayer, aiLayer, merged) {
  if (merged.decision === 'pass') return [];
  const ruleSorted = [...pickArray(ruleLayer?.hits)].sort((a, b) => severityRank(b?.severity) - severityRank(a?.severity));
  for (const h of ruleSorted) {
    const p = normalizeRiskPath(h?.risk_path);
    if (p.length) return p;
  }
  const aiSorted = [...pickArray(aiLayer?.evidence)].sort((a, b) => severityRank(b?.severity) - severityRank(a?.severity));
  for (const e of aiSorted) {
    const p = normalizeRiskPath(e?.risk_path);
    if (p.length) return p;
  }
  return [];
}

function buildEvidenceItems(ruleLayer, aiLayer) {
  const items = [];
  for (const h of pickArray(ruleLayer?.hits)) {
    const pathArr = normalizeRiskPath(h?.risk_path);
    const quotes = pickArray(h?.evidence_items);
    if (quotes.length) {
      for (const q of quotes) {
        items.push({
          source: 'rule',
          id: str(h?.id),
          severity: str(h?.severity).toLowerCase(),
          risk_path: pathArr,
          risk_path_text: riskPathText(pathArr),
          quote: evidenceQuote(q?.quote),
          detail: str(h?.message),
          hard_block: !!h?.hard_block,
        });
      }
      continue;
    }
    items.push({
      source: 'rule',
      id: str(h?.id),
      severity: str(h?.severity).toLowerCase(),
      risk_path: pathArr,
      risk_path_text: riskPathText(pathArr),
      quote: evidenceQuote(h?.message),
      detail: str(h?.message),
      hard_block: !!h?.hard_block,
    });
  }

  for (const e of pickArray(aiLayer?.evidence)) {
    const pathArr = normalizeRiskPath(e?.risk_path);
    items.push({
      source: 'ai',
      id: str(e?.category || 'ai_signal'),
      severity: str(e?.severity).toLowerCase() || 'medium',
      risk_path: pathArr,
      risk_path_text: riskPathText(pathArr),
      quote: evidenceQuote(e?.quote),
      detail: str(e?.category),
      hard_block: false,
    });
  }
  return items.slice(0, 30);
}

function buildReviewQueue(merged, policy, primaryRiskPath) {
  const cfg = policy?.decision?.review_queue || {};
  const enabled = parseToggle(cfg?.enabled, true);
  if (!enabled || merged.decision === 'pass') return null;

  const queueName = str(cfg?.name || 'xhs_manual_review');
  const owner = str(cfg?.owner || 'content_safety');
  const defaultPriority = str(cfg?.default_priority || 'P2');
  const blockPriority = str(cfg?.block_priority || defaultPriority);
  const reviewPriority = str(cfg?.review_priority || defaultPriority);
  const priority = merged.decision === 'block' ? blockPriority : reviewPriority;
  const slaMinutes = toPositiveInt(cfg?.sla_minutes, 60);
  const ts = new Date().toISOString().replace(/[-:.TZ]/g, '').slice(0, 14);
  const pathKey = (riskPathText(primaryRiskPath) || 'unknown').replace(/[^a-z0-9_]+/ig, '_').replace(/^_+|_+$/g, '').toLowerCase();

  return {
    required: true,
    queue_name: queueName,
    owner,
    priority: priority || defaultPriority,
    sla_minutes: slaMinutes,
    review_ticket_id: `rvw_${ts}_${pathKey || 'risk'}`,
    reason: merged.reason,
    risk_path: normalizeRiskPath(primaryRiskPath),
    risk_path_text: riskPathText(primaryRiskPath),
  };
}

async function main(argv) {
  const { values } = parseArgs({
    args: argv,
    options: {
      in: { type: 'string' },
      mode: { type: 'string', default: 'normal' },
      policy: { type: 'string', default: DEFAULT_POLICY_PATH },
      taxonomy: { type: 'string', default: DEFAULT_TAXONOMY_PATH },
      'ai-provider': { type: 'string', default: 'auto' },
      'require-ai': { type: 'string', default: 'off' },
      json: { type: 'boolean', default: true },
      help: { type: 'boolean', default: false },
    },
    allowPositionals: true,
  });

  if (values.help) {
    console.log(usage());
    return;
  }

  if (!values.in) {
    throw new Error('Missing --in <payloadJsonPath>');
  }

  const raw = await readFile(values.in, 'utf8');
  const payload = JSON.parse(raw);
  const mode = str(values.mode || 'normal').toLowerCase();
  const policyPath = str(values.policy) || DEFAULT_POLICY_PATH;
  const loadedPolicy = await loadPolicy(policyPath);
  const taxonomyPath = str(values.taxonomy) || DEFAULT_TAXONOMY_PATH;
  const loadedTaxonomy = await loadTaxonomy(taxonomyPath);
  const taxonomyIndex = buildTaxonomyIndex(loadedTaxonomy.value);
  const policy = deepMerge(DEFAULT_POLICY, loadedPolicy.overrides || {});
  const requireAi = parseToggle(values['require-ai'], false);
  const requestedProvider = str(values['ai-provider'] || policy?.ai?.provider || 'auto').toLowerCase();

  const collected = collectPayload(payload);
  const ruleLayer = buildRuleLayer(collected, policy, mode, taxonomyIndex);
  const aiLayer = await callOpenAiReview({
    collected,
    policy,
    mode,
    ruleLayer,
    taxonomyIndex,
    requestedProvider,
    requireAi,
  });

  const merged = mergeDecision(ruleLayer, aiLayer, policy, requireAi);
  const primaryRiskPath = pickPrimaryRiskPath(ruleLayer, aiLayer, merged);
  const riskPaths = collectAllRiskPaths(ruleLayer, aiLayer);
  const evidenceItems = buildEvidenceItems(ruleLayer, aiLayer);
  const reviewQueue = buildReviewQueue(merged, policy, primaryRiskPath);
  const missing = [];
  if (merged.decision !== 'pass') {
    missing.push('review_pass');
  }

  const result = {
    task: 'xhs_publish_payload_review',
    ok: merged.decision === 'pass',
    mode,
    decision: merged.decision,
    risk_score: merged.risk_score,
    reason: merged.reason,
    risk_path: primaryRiskPath,
    risk_path_text: riskPathText(primaryRiskPath),
    risk_paths: riskPaths.map((x) => ({ path: x, text: riskPathText(x) })),
    evidence: {
      total: evidenceItems.length,
      items: evidenceItems,
    },
    review_queue: reviewQueue,
    policy: {
      review_policy_path: loadedPolicy.path,
      review_taxonomy_path: loadedTaxonomy.path,
      ai_provider_requested: requestedProvider,
      require_ai: requireAi,
      pass_max_risk_score: toFiniteNumber(policy?.decision?.pass_max_risk_score, 28),
      block_min_risk_score: toFiniteNumber(policy?.decision?.block_min_risk_score, 70),
      block_on_review: parseToggle(policy?.decision?.block_on_review, true),
      block_on_ai_error: parseToggle(policy?.decision?.block_on_ai_error, true),
    },
    layers: {
      rule_layer: ruleLayer,
      ai_layer: aiLayer,
    },
    missing,
  };

  if (values.json) {
    console.log(JSON.stringify(result, null, 2));
  } else {
    console.log(`ok: ${result.ok}`);
    console.log(`decision: ${result.decision}`);
    console.log(`risk_score: ${result.risk_score}`);
    console.log(`missing: ${missing.join(', ') || '(none)'}`);
  }

  if (!result.ok) {
    process.exitCode = 2;
  }
}

main(process.argv.slice(2)).catch((e) => {
  console.error(e?.message || String(e));
  process.exitCode = 1;
});

#!/usr/bin/env node
import { parseArgs } from 'node:util';
import { readFile } from 'node:fs/promises';

import { normalizeCookiesPayload } from '../lib/cookies.mjs';

function usage() {
  return `verify_login

Usage:
  node ./scripts/verify_login.mjs --cookies <cookiesJsonPath> --current-url <url> --probe-final-url <url> [--probe-final-url <url> ...] [--probe-status <code>] [--probe-status <code> ...] [--json]

Checks (all required):
  1) left /login
  2) probe final url(s) do not end at /login and status != 401 (if provided)

Bonus (not required):
  - cookies include a session-like cookie (web_session or name contains "session")
`;
}

function normUrl(v) {
  if (!v) return '';
  return String(v).trim();
}

function isLoginUrl(url) {
  const s = normUrl(url).toLowerCase();
  if (!s) return true;
  return s.includes('/login');
}

function hasSessionLikeCookie(cookies) {
  let hasWebSession = false;
  let hasAnySessionName = false;
  for (const c of cookies) {
    if (!c || typeof c !== 'object') continue;
    const name = String(c.name || '').trim();
    const value = String(c.value || '').trim();
    if (!name || !value) continue;
    if (name === 'web_session') hasWebSession = true;
    if (name.toLowerCase().includes('session')) hasAnySessionName = true;
  }
  return {
    has_web_session: hasWebSession,
    has_session_like: hasWebSession || hasAnySessionName,
  };
}

function asArray(v) {
  if (!v) return [];
  return Array.isArray(v) ? v : [v];
}

async function main(argv) {
  const { values } = parseArgs({
    args: argv,
    options: {
      cookies: { type: 'string' },
      'current-url': { type: 'string' },
      'probe-final-url': { type: 'string', multiple: true },
      'probe-status': { type: 'string', multiple: true },
      json: { type: 'boolean', default: true },
      help: { type: 'boolean', default: false },
    },
    allowPositionals: true,
  });

  if (values.help) {
    console.log(usage());
    return;
  }

  if (!values.cookies) {
    throw new Error('Missing --cookies <cookiesJsonPath>');
  }

  const raw = await readFile(values.cookies, 'utf8');
  const parsed = JSON.parse(raw);
  const normalized = normalizeCookiesPayload(parsed);

  const currentUrl = normUrl(values['current-url']);
  const probeFinalUrls = asArray(values['probe-final-url']).map(normUrl).filter(Boolean);
  const probeStatuses = asArray(values['probe-status'])
    .map((x) => Number(x))
    .filter((x) => Number.isFinite(x));
  const sessionLike = hasSessionLikeCookie(normalized.cookies);

  const probeOk =
    probeFinalUrls.length > 0 &&
    probeFinalUrls.every((u) => !isLoginUrl(u)) &&
    probeStatuses.every((s) => s !== 401);

  const checks = {
    left_login: {
      ok: !!currentUrl && !isLoginUrl(currentUrl),
      value: currentUrl || null,
    },
    backend_not_rejected: {
      ok: probeOk,
      value: {
        probe_final_urls: probeFinalUrls,
        probe_statuses: probeStatuses.length ? probeStatuses : null,
      },
    },
    has_session_like_cookie: {
      ok: sessionLike.has_session_like,
      value: {
        has_web_session: sessionLike.has_web_session,
      },
    },
  };

  const requiredChecks = ['left_login', 'backend_not_rejected'];
  const missing = requiredChecks.filter((k) => !checks[k]?.ok);

  const warnings = [];
  if (!checks.has_session_like_cookie.ok) {
    warnings.push(
      'No session-like cookie detected. This may still be OK if the platform changed cookie shape, but expect higher flakiness.'
    );
  }

  const result = {
    ok: missing.length === 0,
    checks,
    cookie_count: normalized.cookies.length,
    missing,
    warnings,
  };

  if (values.json) {
    console.log(JSON.stringify(result, null, 2));
  } else {
    console.log(`ok: ${result.ok}`);
    console.log(`missing: ${result.missing.join(', ') || '(none)'}`);
  }

  if (!result.ok) {
    process.exitCode = 2;
  }
}

main(process.argv.slice(2)).catch((e) => {
  console.error(e?.message || String(e));
  process.exitCode = 1;
});

#!/usr/bin/env node
import { parseArgs } from 'node:util';
import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { getImageSize } from '../lib/image.mjs';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const DEFAULT_POLICY_PATH = path.resolve(__dirname, '../config/verify_publish_policy.json');

function usage() {
  return `verify_publish_payload

Usage:
  node ./scripts/verify_publish_payload.mjs --in <payloadJsonPath> [--mode hot] [--json]
  node ./scripts/verify_publish_payload.mjs --in <payloadJsonPath> [--tag-registry ./data/tag_registry.json]
  node ./scripts/verify_publish_payload.mjs --in <payloadJsonPath> [--policy ./skills/xhs-skill/config/verify_publish_policy.json]

Payload JSON example:
{
  "topic": "今日热点：......",
  "source": {
    "name": "央视新闻",
    "url": "https://...",
    "date": "2026-02-12",
    "evidence_snippet": "2月12日该媒体报道：......",
    "key_facts": ["融资规模约300亿美元", "时间点为2026年2月12日"]
  },
  "post": {
    "title": "标题",
    "body": "正文",
    "tags": ["#热点", "#小红书"],
    "real_topics": ["#人工智能", "#AI热点", "#科技新闻"],
    "media": ["/abs/path/cover.png"]
  }
}
`;
}

const DEFAULT_POLICY = {
  topic: {
    min_len: 4,
  },
  post: {
    title_min_len: 8,
    title_max_len: 20,
    body_min_len: 80,
  },
  tags: {
    min_count: 3,
    max_count: 8,
    placeholder_patterns: [
      '^#?(标签|话题|测试|示例|模板)$',
      '^#?(test|tag|demo|sample|xxx)$',
    ],
  },
  real_topics: {
    min_count: 3,
    max_count: 8,
    placeholder_patterns: [
      '^#?(标签|话题|测试|示例|模板)$',
      '^#?(test|tag|demo|sample|xxx)$',
    ],
  },
  tag_registry: {
    fresh_within_days: 7,
    required_platform: 'xiaohongshu',
  },
  source: {
    evidence_snippet_min_len: 16,
    evidence_snippet_max_len: 180,
    key_facts_min_count: 2,
    key_facts_max_count: 5,
    key_fact_min_len: 8,
    key_fact_max_len: 80,
  },
  media: {
    min_count: 1,
    screenshot_keywords: ['screenshot', 'screen_shot', 'xhs_login', 'login_qr', 'after_click'],
    ratio_target: 3 / 4,
    ratio_tolerance: 0.02,
    preferred_sizes: [{ width: 1242, height: 1660 }],
    max_detail_items: 12,
  },
  anti_ai: {
    template_phrases: [
      '总的来说',
      '综上所述',
      '不难看出',
      '值得注意的是',
      '随着人工智能的发展',
      '随着ai的发展',
      '未来可期',
      '首先',
      '其次',
      '最后',
    ],
    personal_voice_keywords: ['我', '我们', '我觉得', '我观察', '我测了', '我试了', '我踩坑', '我自己', '这周我'],
    week_keywords: ['这周', '本周', '今天', '昨日', '刚刚'],
    strict_min_digit_count: 2,
    strict_min_signal_count: 2,
  },
  link_detection: {
    blocked_tlds: ['com', 'cn', 'net', 'org', 'io', 'me', 'co', 'app', 'dev'],
  },
  hot_mode: {
    source_date_must_be_today: true,
  },
};

function todayISO() {
  const d = new Date();
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

function isScreenshotLike(pathLike, keywords) {
  if (!pathLike) return false;
  const s = String(pathLike).toLowerCase();
  const words = pickArray(keywords).map((x) => str(x).toLowerCase()).filter(Boolean);
  return words.some((w) => s.includes(w));
}

function str(v) {
  return String(v || '').trim();
}

function isValidDateYYYYMMDD(v) {
  return /^\d{4}-\d{2}-\d{2}$/.test(v);
}

function isHttpUrl(v) {
  return /^https?:\/\//i.test(v);
}

function pickArray(v) {
  return Array.isArray(v) ? v : [];
}

function hasLiteralBackslashN(body) {
  const s = String(body || '');
  return s.includes('\\n');
}

function hasSlashNToken(body) {
  const s = String(body || '');
  return /(^|\s)\/n(\s|$)/.test(s);
}

function containsLinkLike(text, blockedTlds) {
  const s = String(text || '').trim();
  if (!s) return false;
  if (/https?:\/\//i.test(s)) return true;
  if (/www\./i.test(s)) return true;
  const tlds = uniqueList(pickArray(blockedTlds).map((x) => str(x).toLowerCase()).filter(Boolean));
  if (!tlds.length) return false;
  const tldPattern = tlds.map((x) => x.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|');
  if (!tldPattern) return false;
  // very rough domain detection; intentionally strict to avoid accidental bans
  const domainLike = new RegExp(`\\b[a-z0-9-]+\\.(${tldPattern})\\b`, 'i');
  if (domainLike.test(s)) return true;
  return false;
}

function normalizeTag(tag) {
  const v = str(tag);
  if (!v) return '';
  return v.startsWith('#') ? v : `#${v}`;
}

function uniqueList(items) {
  const out = [];
  const seen = new Set();
  for (const it of items) {
    const v = str(it);
    if (!v) continue;
    const k = v.toLowerCase();
    if (seen.has(k)) continue;
    seen.add(k);
    out.push(v);
  }
  return out;
}

function parseDateSafe(iso) {
  const s = str(iso);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return null;
  const d = new Date(`${s}T00:00:00`);
  if (Number.isNaN(d.getTime())) return null;
  return d;
}

function toPositiveInt(value, fallback) {
  const n = Number(value);
  if (!Number.isFinite(n) || n <= 0) return fallback;
  return Math.floor(n);
}

function parseToggle(value, fallback = true) {
  const s = String(value ?? '').trim().toLowerCase();
  if (!s) return fallback;
  if (['1', 'true', 'on', 'yes', 'y'].includes(s)) return true;
  if (['0', 'false', 'off', 'no', 'n'].includes(s)) return false;
  return fallback;
}

function toFiniteNumber(value, fallback) {
  const n = Number(value);
  if (!Number.isFinite(n)) return fallback;
  return n;
}

function isPlainObject(v) {
  return !!v && typeof v === 'object' && !Array.isArray(v);
}

function deepMerge(base, override) {
  if (Array.isArray(base)) {
    return Array.isArray(override) ? override : [...base];
  }
  if (isPlainObject(base)) {
    const out = { ...base };
    if (isPlainObject(override)) {
      for (const key of Object.keys(override)) {
        if (Object.prototype.hasOwnProperty.call(base, key)) {
          out[key] = deepMerge(base[key], override[key]);
        } else {
          out[key] = override[key];
        }
      }
    }
    return out;
  }
  return override === undefined ? base : override;
}

function compileRegexList(patterns, fallbackPatterns = []) {
  const out = [];
  const input = pickArray(patterns);
  for (const raw of input) {
    const source = str(raw);
    if (!source) continue;
    try {
      out.push(new RegExp(source, 'i'));
    } catch {
      // Ignore invalid custom regex patterns; defaults still apply.
    }
  }
  if (out.length > 0 || input.length === 0) return out;
  if (!fallbackPatterns.length) return out;
  return compileRegexList(fallbackPatterns, []);
}

function hasAnyKeyword(text, keywords) {
  const s = String(text || '');
  if (!s) return false;
  const words = pickArray(keywords).map((x) => str(x)).filter(Boolean);
  return words.some((w) => s.includes(w));
}

async function loadPolicy(filePath, { allowMissing = false } = {}) {
  const policyPath = str(filePath);
  if (!policyPath) {
    return { exists: false, path: null, overrides: {}, error: null };
  }
  try {
    const raw = await readFile(policyPath, 'utf8');
    const parsed = JSON.parse(raw);
    if (!isPlainObject(parsed)) {
      throw new Error(`Policy file is not a JSON object: ${policyPath}`);
    }
    return { exists: true, path: policyPath, overrides: parsed, error: null };
  } catch (e) {
    const code = e?.code || '';
    if (allowMissing && code === 'ENOENT') {
      return { exists: false, path: policyPath, overrides: {}, error: null };
    }
    throw new Error(`Failed to load policy file "${policyPath}": ${e?.message || String(e)}`);
  }
}

function daysSince(isoDate) {
  const d = parseDateSafe(isoDate);
  if (!d) return null;
  const now = new Date();
  const nowAtDay = new Date(`${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}T00:00:00`);
  const diff = nowAtDay.getTime() - d.getTime();
  return Math.floor(diff / (24 * 60 * 60 * 1000));
}

async function loadTagRegistry(filePath) {
  try {
    const raw = await readFile(filePath, 'utf8');
    const data = JSON.parse(raw);
    const tagsRaw = Array.isArray(data)
      ? data
      : Array.isArray(data?.tags)
        ? data.tags
        : [];
    const normalized = uniqueList(tagsRaw.map(normalizeTag).filter(Boolean));
    return {
      exists: true,
      path: filePath,
      updated_at: str(data?.updated_at) || null,
      source: data?.source && typeof data.source === 'object' ? data.source : null,
      tags: normalized,
    };
  } catch {
    return {
      exists: false,
      path: filePath,
      updated_at: null,
      source: null,
      tags: [],
    };
  }
}

function hasAiTemplateStyle(body, phrases) {
  const s = String(body || '').toLowerCase();
  const templates = pickArray(phrases).map((x) => str(x)).filter(Boolean);
  return templates.filter((p) => s.includes(p.toLowerCase()));
}

function hasPersonalVoice(body, keywords) {
  return hasAnyKeyword(body, keywords);
}

function hasConcreteSignals({ body, sourceName, sourceDate, strictAntiAi, policy }) {
  const s = String(body || '');
  const minDigitCount = toPositiveInt(policy?.anti_ai?.strict_min_digit_count, 2);
  const minSignalCount = toPositiveInt(policy?.anti_ai?.strict_min_signal_count, 2);
  const weekKeywords = pickArray(policy?.anti_ai?.week_keywords);
  const digitCount = (s.match(/\d/g) || []).length;
  const hasDateLike = /\d{4}[年\-/.]\d{1,2}[月\-/.]\d{1,2}日?/.test(s) || /\d{1,2}月\d{1,2}日/.test(s);
  const hasAmountLike = /\d+\s*(亿|万|%|美元|人民币|条|家|款|次)/.test(s);
  const hasSourceMention = !!sourceName && s.includes(sourceName);
  const hasWeekMention = hasAnyKeyword(s, weekKeywords) || (!!sourceDate && s.includes(sourceDate));
  const hasHardFactSignal = digitCount >= minDigitCount || hasDateLike || hasAmountLike;
  const signalCount = [digitCount >= minDigitCount, hasDateLike, hasAmountLike, hasSourceMention, hasWeekMention].filter(Boolean).length;
  return {
    ok: strictAntiAi ? hasSourceMention && hasHardFactSignal && signalCount >= minSignalCount : signalCount >= 1,
    value: {
      digit_count: digitCount,
      min_digit_count: minDigitCount,
      has_date_like: hasDateLike,
      has_amount_like: hasAmountLike,
      has_source_mention: hasSourceMention,
      has_week_mention: hasWeekMention,
      has_hard_fact_signal: hasHardFactSignal,
      signal_count: signalCount,
      strict_min_signal_count: minSignalCount,
      strict_anti_ai: strictAntiAi,
    },
  };
}

function hasPlaceholderTag(tags, compiledPatterns) {
  const hit = [];
  for (const t of tags) {
    const x = str(t);
    if (!x) continue;
    if (compiledPatterns.some((re) => re.test(x))) hit.push(x);
  }
  return hit;
}

function isImagePath(p) {
  const s = String(p || '').toLowerCase();
  return s.endsWith('.png') || s.endsWith('.jpg') || s.endsWith('.jpeg');
}

async function checkMediaDims(media, policy) {
  const images = media.filter(isImagePath);
  const results = [];
  for (const p of images) {
    try {
      const { width, height, format } = await getImageSize(p);
      const ratio = width / height;
      results.push({ path: p, ok: true, width, height, ratio, format });
    } catch (e) {
      results.push({ path: p, ok: false, error: e?.message || String(e) });
    }
  }

  // Strict-ish: expect portrait 3:4 assets for XHS cards (prefer 1242x1660).
  const ratioTarget = toFiniteNumber(policy?.media?.ratio_target, 3 / 4);
  const ratioTol = toFiniteNumber(policy?.media?.ratio_tolerance, 0.02);
  const preferredSizes = pickArray(policy?.media?.preferred_sizes);
  const maxDetailItems = toPositiveInt(policy?.media?.max_detail_items, 12);
  const bad = results.filter((r) => r.ok && Math.abs(r.ratio - ratioTarget) > ratioTol);
  const parseFailed = results.filter((r) => !r.ok);

  const hasAny = images.length > 0;
  const ok = !hasAny || (bad.length === 0 && parseFailed.length === 0);

  const perfect = results.filter((r) =>
    r.ok &&
    preferredSizes.some((s) => r.width === toPositiveInt(s?.width, -1) && r.height === toPositiveInt(s?.height, -1))
  );
  return {
    ok,
    value: {
      checked_images: images.length,
      passed: results.filter((r) => r.ok).length,
      parse_failed: parseFailed.length,
      ratio_bad: bad.length,
      perfect_1242x1660: perfect.length,
      preferred_size_matched: perfect.length,
      details: results.slice(0, maxDetailItems), // keep output bounded
    },
  };
}

async function buildChecks(payload, mode, { policy, tagRegistry, allowUnverifiedTags, minRegistryTags, requireSourceEvidence, strictAntiAi }) {
  const topic = str(payload?.topic);
  const sourceName = str(payload?.source?.name);
  const sourceUrl = str(payload?.source?.url);
  const sourceDate = str(payload?.source?.date);
  const sourceEvidenceSnippet = str(payload?.source?.evidence_snippet);
  const sourceKeyFacts = uniqueList(pickArray(payload?.source?.key_facts).map((x) => str(x)).filter(Boolean));

  const title = str(payload?.post?.title);
  const body = str(payload?.post?.body);
  const tagsRaw = pickArray(payload?.post?.tags).map((x) => normalizeTag(x)).filter(Boolean);
  const tags = tagsRaw.filter((x) => x.startsWith('#'));
  const realTopicsRaw = pickArray(payload?.post?.real_topics).map((x) => normalizeTag(x)).filter(Boolean);
  const realTopics = realTopicsRaw.filter((x) => x.startsWith('#'));
  const media = pickArray(payload?.post?.media).map((x) => str(x)).filter(Boolean);

  const topicMinLen = toPositiveInt(policy?.topic?.min_len, 4);
  const titleMinLen = toPositiveInt(policy?.post?.title_min_len, 8);
  const titleMaxLen = Math.max(titleMinLen, toPositiveInt(policy?.post?.title_max_len, 20));
  const bodyMinLen = toPositiveInt(policy?.post?.body_min_len, 80);
  const tagMinCount = toPositiveInt(policy?.tags?.min_count, 3);
  const tagMaxCount = Math.max(tagMinCount, toPositiveInt(policy?.tags?.max_count, 8));
  const realTopicMinCount = toPositiveInt(policy?.real_topics?.min_count, 3);
  const realTopicMaxCount = Math.max(realTopicMinCount, toPositiveInt(policy?.real_topics?.max_count, 8));
  const registryFreshWithinDays = toPositiveInt(policy?.tag_registry?.fresh_within_days, 7);
  const requiredRegistryPlatform = str(policy?.tag_registry?.required_platform || 'xiaohongshu').toLowerCase();
  const sourceEvidenceMinLen = toPositiveInt(policy?.source?.evidence_snippet_min_len, 16);
  const sourceEvidenceMaxLen = Math.max(sourceEvidenceMinLen, toPositiveInt(policy?.source?.evidence_snippet_max_len, 180));
  const keyFactMinCount = toPositiveInt(policy?.source?.key_facts_min_count, 2);
  const keyFactMaxCount = Math.max(keyFactMinCount, toPositiveInt(policy?.source?.key_facts_max_count, 5));
  const keyFactMinLen = toPositiveInt(policy?.source?.key_fact_min_len, 8);
  const keyFactMaxLen = Math.max(keyFactMinLen, toPositiveInt(policy?.source?.key_fact_max_len, 80));
  const mediaMinCount = toPositiveInt(policy?.media?.min_count, 1);
  const screenshotKeywords = pickArray(policy?.media?.screenshot_keywords);
  const blockedTlds = pickArray(policy?.link_detection?.blocked_tlds);
  const tagPlaceholderPatterns = compileRegexList(policy?.tags?.placeholder_patterns, DEFAULT_POLICY.tags.placeholder_patterns);
  const realTopicPlaceholderPatterns = compileRegexList(policy?.real_topics?.placeholder_patterns, DEFAULT_POLICY.real_topics.placeholder_patterns);
  const hotSourceDateMustBeToday = parseToggle(policy?.hot_mode?.source_date_must_be_today, true);

  const titleLen = [...title].length;
  const bodyLen = [...body].length;
  const screenshotOnly = media.length > 0 && media.every((x) => isScreenshotLike(x, screenshotKeywords));
  const hotMode = mode === 'hot';
  const hasBackslashN = hasLiteralBackslashN(body);
  const hasSlashN = hasSlashNToken(body);
  const mediaDims = await checkMediaDims(media, policy);
  const linkInTitle = containsLinkLike(title, blockedTlds);
  const linkInBody = containsLinkLike(body, blockedTlds);
  const linkInTags = tagsRaw.some((t) => containsLinkLike(t, blockedTlds));
  const linkInMediaPath = media.some((p) => containsLinkLike(p, blockedTlds) || String(p).includes('://'));
  const duplicateTagCount = tagsRaw.length - uniqueList(tagsRaw).length;
  const duplicateRealTopicCount = realTopicsRaw.length - uniqueList(realTopicsRaw).length;
  const placeholderTags = hasPlaceholderTag(tagsRaw, tagPlaceholderPatterns);
  const placeholderRealTopics = hasPlaceholderTag(realTopicsRaw, realTopicPlaceholderPatterns);
  const aiTemplateHits = hasAiTemplateStyle(body, policy?.anti_ai?.template_phrases);
  const personalVoice = hasPersonalVoice(body, policy?.anti_ai?.personal_voice_keywords);
  const concreteSignals = hasConcreteSignals({ body, sourceName, sourceDate, strictAntiAi, policy });
  const registryTagSet = new Set((tagRegistry?.tags || []).map((x) => str(x).toLowerCase()));
  const unverifiedTags = tags.filter((t) => !registryTagSet.has(str(t).toLowerCase()));
  const unverifiedRealTopics = realTopics.filter((t) => !registryTagSet.has(str(t).toLowerCase()));
  const registryAgeDays = daysSince(tagRegistry?.updated_at);
  const registryFresh = registryAgeDays !== null && registryAgeDays >= 0 && registryAgeDays <= registryFreshWithinDays;
  const registrySourcePlatform = str(tagRegistry?.source?.platform).toLowerCase();
  const registrySourceMethod = str(tagRegistry?.source?.method);

  const sourceEvidenceOk =
    !requireSourceEvidence ||
    (sourceEvidenceSnippet.length >= sourceEvidenceMinLen &&
      sourceEvidenceSnippet.length <= sourceEvidenceMaxLen &&
      !containsLinkLike(sourceEvidenceSnippet, blockedTlds) &&
      (!!sourceName && sourceEvidenceSnippet.includes(sourceName)));

  const sourceKeyFactLengthBad = sourceKeyFacts.filter((x) => x.length < keyFactMinLen || x.length > keyFactMaxLen);
  const sourceKeyFactLinkBad = sourceKeyFacts.filter((x) => containsLinkLike(x, blockedTlds));
  const sourceKeyFactHasDateOrNumber = sourceKeyFacts.some(
    (x) => /\d/.test(x) || /\d{4}[年\-/.]\d{1,2}[月\-/.]\d{1,2}日?/.test(x) || /\d{1,2}月\d{1,2}日/.test(x)
  );
  const sourceKeyFactsOk =
    !requireSourceEvidence ||
    (sourceKeyFacts.length >= keyFactMinCount &&
      sourceKeyFacts.length <= keyFactMaxCount &&
      sourceKeyFactLengthBad.length === 0 &&
      sourceKeyFactLinkBad.length === 0 &&
      sourceKeyFactHasDateOrNumber);

  const checks = {
    has_topic: {
      ok: topic.length >= topicMinLen,
      value: topic || null,
    },
    has_source: {
      ok: !!sourceName && isHttpUrl(sourceUrl) && isValidDateYYYYMMDD(sourceDate),
      value: { name: sourceName || null, url: sourceUrl || null, date: sourceDate || null },
    },
    source_evidence_snippet_ok: {
      ok: sourceEvidenceOk,
      value: {
        required: requireSourceEvidence,
        min_len: sourceEvidenceMinLen,
        max_len: sourceEvidenceMaxLen,
        length: sourceEvidenceSnippet.length,
        contains_source_name: !!sourceName && sourceEvidenceSnippet.includes(sourceName),
      },
    },
    source_key_facts_ok: {
      ok: sourceKeyFactsOk,
      value: {
        required: requireSourceEvidence,
        min_count: keyFactMinCount,
        max_count: keyFactMaxCount,
        min_len: keyFactMinLen,
        max_len: keyFactMaxLen,
        count: sourceKeyFacts.length,
        bad_length: sourceKeyFactLengthBad,
        has_link_like: sourceKeyFactLinkBad,
        has_date_or_number_signal: sourceKeyFactHasDateOrNumber,
      },
    },
    title_ok: {
      ok: titleLen >= titleMinLen && titleLen <= titleMaxLen,
      value: { title: title || null, length: titleLen, min_len: titleMinLen, max_len: titleMaxLen },
    },
    body_ok: {
      ok: bodyLen >= bodyMinLen,
      value: { length: bodyLen, min_len: bodyMinLen },
    },
    body_newline_normalized: {
      // Allow literal "\\n" in payload (we can normalize before writing), but forbid "/n" token.
      ok: !hasSlashN,
      value: {
        has_literal_backslash_n: hasBackslashN,
        has_slash_n_token: hasSlashN,
      },
    },
    tags_ok: {
      ok: tags.length >= tagMinCount && tags.length <= tagMaxCount && duplicateTagCount === 0,
      value: { count: tags.length, min_count: tagMinCount, max_count: tagMaxCount, duplicate_count: duplicateTagCount, tags },
    },
    tags_not_placeholder: {
      ok: placeholderTags.length === 0,
      value: {
        hit: placeholderTags,
      },
    },
    real_topics_ok: {
      ok: realTopics.length >= realTopicMinCount && realTopics.length <= realTopicMaxCount && duplicateRealTopicCount === 0,
      value: {
        count: realTopics.length,
        min_count: realTopicMinCount,
        max_count: realTopicMaxCount,
        duplicate_count: duplicateRealTopicCount,
        real_topics: realTopics,
      },
    },
    real_topics_not_placeholder: {
      ok: placeholderRealTopics.length === 0,
      value: {
        hit: placeholderRealTopics,
      },
    },
    tag_registry_meta_ok: {
      ok:
        tagRegistry.exists &&
        registryFresh &&
        tagRegistry.tags.length >= minRegistryTags &&
        registrySourcePlatform === requiredRegistryPlatform &&
        !!registrySourceMethod,
      value: {
        registry_exists: !!tagRegistry.exists,
        registry_path: tagRegistry.path,
        registry_updated_at: tagRegistry.updated_at,
        registry_age_days: registryAgeDays,
        registry_fresh: registryFresh,
        registry_fresh_within_days: registryFreshWithinDays,
        registry_fresh_within_days_7: registryFresh,
        registry_tag_count: tagRegistry.tags.length,
        min_registry_tags: minRegistryTags,
        source_platform: registrySourcePlatform || null,
        required_source_platform: requiredRegistryPlatform || null,
        source_method: registrySourceMethod || null,
      },
    },
    tags_from_registry: {
      ok: allowUnverifiedTags || (tagRegistry.exists && registryFresh && unverifiedTags.length === 0),
      value: {
        allow_unverified_tags: allowUnverifiedTags,
        registry_exists: !!tagRegistry.exists,
        registry_path: tagRegistry.path,
        registry_updated_at: tagRegistry.updated_at,
        registry_age_days: registryAgeDays,
        registry_fresh: registryFresh,
        registry_fresh_within_days: registryFreshWithinDays,
        registry_fresh_within_days_7: registryFresh,
        registry_tag_count: tagRegistry.tags.length,
        unverified_tags: unverifiedTags,
      },
    },
    real_topics_from_registry: {
      ok: allowUnverifiedTags || (tagRegistry.exists && registryFresh && unverifiedRealTopics.length === 0),
      value: {
        allow_unverified_tags: allowUnverifiedTags,
        registry_exists: !!tagRegistry.exists,
        registry_path: tagRegistry.path,
        registry_updated_at: tagRegistry.updated_at,
        registry_age_days: registryAgeDays,
        registry_fresh: registryFresh,
        registry_fresh_within_days: registryFreshWithinDays,
        registry_fresh_within_days_7: registryFresh,
        registry_tag_count: tagRegistry.tags.length,
        unverified_real_topics: unverifiedRealTopics,
      },
    },
    no_links_in_content: {
      ok: !(linkInTitle || linkInBody || linkInTags),
      value: {
        title: linkInTitle,
        body: linkInBody,
        tags: linkInTags,
      },
    },
    no_links_in_media_path: {
      ok: !linkInMediaPath,
      value: linkInMediaPath ? media : null,
    },
    media_ok: {
      ok: media.length >= mediaMinCount && !screenshotOnly,
      value: { count: media.length, min_count: mediaMinCount, screenshot_only: screenshotOnly, media },
    },
    media_dim_ok: mediaDims,
    anti_ai_personal_voice: {
      ok: personalVoice,
      value: { has_personal_voice: personalVoice },
    },
    anti_ai_concrete_signals: concreteSignals,
    anti_ai_source_mentioned_in_body: {
      ok: !!sourceName && body.includes(sourceName),
      value: {
        source_name: sourceName || null,
        mentioned: !!sourceName && body.includes(sourceName),
      },
    },
    anti_ai_template_phrase: {
      ok: aiTemplateHits.length === 0,
      value: {
        hit: aiTemplateHits,
      },
    },
    hot_source_is_today: {
      ok: !hotMode || !hotSourceDateMustBeToday || sourceDate === todayISO(),
      value: {
        source_date_must_be_today: hotSourceDateMustBeToday,
        required_date: hotMode && hotSourceDateMustBeToday ? todayISO() : null,
        source_date: sourceDate || null,
      },
    },
  };

  return checks;
}

async function main(argv) {
  const { values } = parseArgs({
    args: argv,
    options: {
      in: { type: 'string' },
      mode: { type: 'string', default: 'normal' },
      policy: { type: 'string', default: DEFAULT_POLICY_PATH },
      'tag-registry': { type: 'string', default: './data/tag_registry.json' },
      'allow-unverified-tags': { type: 'boolean', default: false },
      'min-registry-tags': { type: 'string', default: '12' },
      'require-source-evidence': { type: 'string', default: 'on' },
      'strict-anti-ai': { type: 'string', default: 'on' },
      json: { type: 'boolean', default: true },
      help: { type: 'boolean', default: false },
    },
    allowPositionals: true,
  });

  if (values.help) {
    console.log(usage());
    return;
  }

  if (!values.in) {
    throw new Error('Missing --in <payloadJsonPath>');
  }

  const raw = await readFile(values.in, 'utf8');
  const payload = JSON.parse(raw);
  const mode = str(values.mode || 'normal').toLowerCase();
  const policyFilePath = str(values.policy) || DEFAULT_POLICY_PATH;
  const customPolicy = await loadPolicy(policyFilePath, { allowMissing: false });
  const effectivePolicy = deepMerge(DEFAULT_POLICY, customPolicy.overrides || {});
  const tagRegistryPath = str(values['tag-registry']) || './data/tag_registry.json';
  const tagRegistry = await loadTagRegistry(tagRegistryPath);
  const allowUnverifiedTags = !!values['allow-unverified-tags'];
  const minRegistryTags = toPositiveInt(values['min-registry-tags'], 12);
  const requireSourceEvidence = parseToggle(values['require-source-evidence'], true);
  const strictAntiAi = parseToggle(values['strict-anti-ai'], true);
  const checks = await buildChecks(payload, mode, {
    policy: effectivePolicy,
    tagRegistry,
    allowUnverifiedTags,
    minRegistryTags,
    requireSourceEvidence,
    strictAntiAi,
  });

  const missing = Object.entries(checks)
    .filter(([, item]) => !item.ok)
    .map(([key]) => key);

  const result = {
    task: 'xhs_publish_payload_validate',
    ok: missing.length === 0,
    mode,
    policy: {
      policy_path: customPolicy.path,
      policy_loaded: customPolicy.exists,
      tag_registry_path: tagRegistry.path,
      allow_unverified_tags: allowUnverifiedTags,
      min_registry_tags: minRegistryTags,
      require_source_evidence: requireSourceEvidence,
      anti_ai_style_required: true,
      strict_anti_ai: strictAntiAi,
      policy_snapshot: effectivePolicy,
    },
    checks,
    missing,
  };

  if (values.json) {
    console.log(JSON.stringify(result, null, 2));
  } else {
    console.log(`ok: ${result.ok}`);
    console.log(`missing: ${missing.join(', ') || '(none)'}`);
  }

  if (!result.ok) {
    process.exitCode = 2;
  }
}

main(process.argv.slice(2)).catch((e) => {
  console.error(e?.message || String(e));
  process.exitCode = 1;
});
